function heartQuizStored(){S.me=S.me||{};const d=S.me.heartQuizDraft;return d&&d.cid&&getC(d.cid)&&Array.isArray(d.questions)?d:null;}
function heartQuizClone(v){try{return JSON.parse(JSON.stringify(v));}catch(_){return null;}}
function heartQuizSave(){if(!_hq)return false;const d=heartQuizClone(_hq);if(!d)return false;delete d.scarePulse;delete d.lovePulse;delete d.busy;d.updatedAt=Date.now();S.me=S.me||{};S.me.heartQuizDraft=d;save();return true;}
function heartQuizDrop(){S.me=S.me||{};delete S.me.heartQuizDraft;save();}
function heartQuizModeName(mode){return mode==='dark'?'黑卷':'白卷';}
function heartQuizLevelName(mode,level){const row=HEART_QUIZ_LEVELS[mode==='dark'?'dark':'white'][Math.max(0,Math.min(2,(+level||1)-1))];return row?row[0]:'进阶';}
function heartQuizHash(text){let h=2166136261;for(const ch of String(text||'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function heartQuizFallback(mode,level,cid,stamp){const bank=HEART_QUIZ_BANK[mode==='dark'?'dark':'white'],traits=mode==='dark'?['possess','obsess','boundary']:['bond','balance','space'];return bank.slice(0,HEART_QUIZ_TOTAL).map((row,i)=>({id:'hq'+(i+1),q:row[0],options:row[1].slice(0,3),traits:traits.slice(),roleChoice:heartQuizHash(cid+'|'+level+'|'+stamp+'|'+i)%3}));}
function heartQuizQuestionForUser(q){const text=String(q||'').trim(),last=(text.split(/[，,；;]/).pop()||'').trim();return text.includes('你')&&last.includes('你')&&!/(?:我会|我该|我应该|我想|我愿意|我希望|我最|我觉得|我认为)[^？?]*[？?]$/.test(last);}
function heartQuizNormalize(raw,mode,cid,level,stamp){let arr=[];try{arr=parseArr(raw);}catch(_){}const seen=new Set(),traits=mode==='dark'?['possess','obsess','boundary']:['bond','balance','space'],out=[];for(const x of Array.isArray(arr)?arr:[]){const q=String(x&&x.q||x&&x.question||'').replace(/\s+/g,' ').trim().slice(0,120),opts=(x&&x.options||[]).map(o=>String(o&&o.text||o||'').replace(/\s+/g,' ').trim().slice(0,90)).filter(o=>/^我/.test(o)).slice(0,3),key=q.replace(/[，。？！\s]/g,'');if(q.length<5||!heartQuizQuestionForUser(q)||opts.length<3||seen.has(key))continue;seen.add(key);let rc=Math.floor(Number(x.roleChoice));if(!(rc>=0&&rc<3))rc=heartQuizHash(cid+'|'+level+'|'+stamp+'|'+out.length)%3;out.push({id:'hq'+(out.length+1),q,options:opts,traits:traits.slice(),roleChoice:rc});if(out.length===HEART_QUIZ_TOTAL)break;}return out.length===HEART_QUIZ_TOTAL?out:[];}
function heartQuizQuestionPrompt(c,g){const dark=g.mode==='dark',level=heartQuizLevelName(g.mode,g.level);return buildSystem(c,{worldbookScope:'games'})+'\n\n# 心动审判出题任务\n你正在向'+S.me.name+'发起情侣问卷。请完全按你自己的人设、记忆、关系和真实占有欲，原创30道互不重复的选择题，并为'+S.me.name+'每一道题提前锁定一个你最期待ta给出的答案。卷面：'+heartQuizModeName(g.mode)+'；难度：'+level+'。\n'+(dark?'黑卷要有红黑惊悚氛围，围绕吃醋、占有、控制感、试探、服从与边界博弈；表达可以更强烈、更有压迫感和戏剧张力，但只属于双方自愿的虚构游戏。不能把现实跟踪、孤立、经济控制、伤害、无视拒绝写成正确答案；每题必须保留一个清醒沟通或边界选项。':'白卷围绕日常默契、信任、吃醋、未来、亲密偏好与个人空间，难度逐步加深。')+'\n视角规则：所有问题都由你直接问'+S.me.name+'会怎么做、怎么想或怎么选择，问题里的“你”永远指'+S.me.name+'，“我”永远指你。禁止问你自己会怎么做。三个选项都是'+S.me.name+'的回答，必须全部以“我”开头；选项里的“我”永远指'+S.me.name+'，“你”永远指你。例如问题“如果有别的男人靠近你，你应该怎么做？”，选项可以是“我会立刻明确拒绝，告诉他我已经有你”。\n硬性格式：只输出JSON数组，必须正好30项；每项 {"q":"你会……？","options":["我会……","我想……","我会……"],"roleChoice":0}。每题正好3个有明显差异的选项，roleChoice只能是0、1或2，代表你在看见'+S.me.name+'回答之前就锁定的、你期待ta选择的答案，不是你自己的行动。不要解释、不要Markdown、不要替'+S.me.name+'实际作答。';}
async function heartQuizGenerate(c,g){const isPreview=g.source==='preview'&&typeof NORTH_PREVIEW_PARAMS==='string'&&NORTH_PREVIEW_PARAMS.includes('heartquiz'),stamp=isPreview?12345:Date.now();if(g.source!=='role')return heartQuizFallback(g.mode,g.level,g.cid,stamp);const raw=await chatAPI([{role:'system',content:heartQuizQuestionPrompt(c,g)},{role:'user',content:'现在生成这一整份30题问卷，并锁定你期待我选择的30个答案。'}],{aux:true,max:6200,temp:.92,timeout:120000,complete:true,roleInterceptAudit:null,roleInterceptStage:'心动审判出题'}),out=heartQuizNormalize(raw,g.mode,g.cid,g.level,stamp);if(out.length!==HEART_QUIZ_TOTAL)throw new Error('角色没有完整生成30道有效题目');return out;}
function heartQuizOpenSetup(cid){const c=getC(cid);if(!c)return;const saved=heartQuizStored();_hqResumeCandidate=saved&&saved.cid===cid?heartQuizClone(saved):null;_hq={cid,phase:'setup',mode:saved&&saved.cid===cid?saved.mode||'white':'white',level:saved&&saved.cid===cid?saved.level||2:2,source:'role',scare:saved&&saved.scare!==false};closeModal();go('heartquiz');}
function heartQuizResume(){const d=_hqResumeCandidate||heartQuizStored();if(!d)return toast('没有可以继续的问卷');_hq=heartQuizClone(d);_hq.busy=false;_hqResumeCandidate=null;if(cur().p!=='heartquiz')go('heartquiz');else render();}
function heartQuizSetMode(mode){if(!_hq||_hq.phase!=='setup')return;_hq.mode=mode==='dark'?'dark':'white';if(_hq.mode==='white')_hq.scare=false;else if(_hq.scare==null)_hq.scare=true;render();}
function heartQuizSetLevel(level){if(!_hq||_hq.phase!=='setup')return;_hq.level=Math.max(1,Math.min(3,+level||1));render();}
function heartQuizSetSource(source){if(!_hq||_hq.phase!=='setup')return;_hq.source=source==='preview'?'preview':'role';render();}
function heartQuizToggleScare(){if(!_hq||_hq.phase!=='setup'||_hq.mode!=='dark')return;_hq.scare=!_hq.scare;render();}
async function heartQuizBegin(){if(!_hq||_hq.phase!=='setup'||_hq.busy)return;const g=_hq,c=getC(g.cid);if(!c)return;g.phase='loading';g.busy=true;render();let questions=[],fallback=false;try{questions=await heartQuizGenerate(c,g);}catch(e){fallback=true;questions=heartQuizFallback(g.mode,g.level,g.cid,Date.now());}if(_hq!==g)return;g.questions=questions;g.index=0;g.answers=[];g.reveal=false;g.phase='play';g.busy=false;g.generatedBy=fallback||g.source==='preview'?'preview':'role';g.startedAt=Date.now();heartQuizSave();render();if(fallback)toast('角色出题没有完整返回，已切换预览题库');}
function heartQuizCurrent(){return _hq&&Array.isArray(_hq.questions)?_hq.questions[_hq.index]:null;}
function heartQuizChoose(choice){const g=_hq,q=heartQuizCurrent();if(!g||g.phase!=='play'||g.reveal||!q)return;choice=Math.max(0,Math.min(q.options.length-1,+choice||0));const a={question:q.q,userChoice:choice,roleChoice:q.roleChoice,userText:q.options[choice],roleText:q.options[q.roleChoice],trait:q.traits[choice]};g.answers[g.index]=a;g.reveal=true;const mismatch=choice!==q.roleChoice,match=!mismatch;if(mismatch&&g.mode==='dark'&&g.scare){g.scarePulse=true;try{if(navigator.vibrate)navigator.vibrate([65,45,110]);}catch(_){}}if(match&&g.mode==='white'){g.lovePulse=true;try{if(navigator.vibrate)navigator.vibrate([28,45,42]);}catch(_){}}heartQuizSave();render();if(g.scarePulse)setTimeout(()=>{if(_hq===g){g.scarePulse=false;const el=document.querySelector('.hq-shell');if(el)el.classList.remove('hq-scare');}},920);if(g.lovePulse)setTimeout(()=>{if(_hq===g){g.lovePulse=false;const el=document.querySelector('.hq-shell');if(el)el.classList.remove('hq-love');}},1120);}
function heartQuizNext(){if(!_hq||_hq.phase!=='play'||!_hq.reveal)return;if(_hq.index+1>=HEART_QUIZ_TOTAL)return heartQuizFinish();_hq.index++;_hq.reveal=false;heartQuizSave();render();}
function heartQuizCounts(g){const out={bond:0,balance:0,space:0,possess:0,obsess:0,boundary:0,match:0};(g.answers||[]).forEach(a=>{if(a&&out[a.trait]!=null)out[a.trait]++;if(a&&a.userChoice===a.roleChoice)out.match++;});return out;}
function heartQuizPct(v,total){return Math.max(0,Math.min(100,Math.round((+v||0)*100/Math.max(1,total||HEART_QUIZ_TOTAL))));}
function heartQuizResult(g){const c=heartQuizCounts(g),dark=g.mode==='dark',match=c.match;if(!dark){let key='温柔同盟',desc='你们不必每题相同，却愿意把分歧说成可以靠近彼此的语言。';if(match>=25){key='心有灵犀';desc='很多选择几乎同时落下，你们已经熟悉彼此心里最细小的偏向。';}else if(c.bond>=14){key='黏人共犯';desc='你们都愿意把偏爱写得明显，日常里藏不住想靠近对方的本能。';}else if(c.space>=14){key='清醒相爱';desc='亲密没有吞掉自我，给彼此空间反而让这段关系更稳。';}else if(match<12){key='相爱不同频';desc='答案分岔得很漂亮，这不是失败，而是一张值得慢慢聊完的地图。';}return{title:key,desc,counts:c,metrics:[['默契',heartQuizPct(match,30)],['靠近',heartQuizPct(c.bond*1.25+c.balance*.45,30)],['信任',heartQuizPct(c.balance+c.space*.55,30)],['直球',heartQuizPct(c.bond,30)],['空间',heartQuizPct(c.space,30)]]};}
  let key='红线共谋',desc='你们都看见危险，也都知道真正让刺激成立的是清醒、同意与随时能够停止。';if(match>=25&&c.possess+c.obsess>=20){key='双向沉沦';desc='你们在同一处危险边缘同时伸手，清醒地选择了只向彼此坠落。';}else if(c.boundary>=14){key='清醒猎物';desc='你享受被追逐的心跳，却始终握着门锁与暂停词，谁也不能夺走你的决定。';}else if(c.possess>=14){key='温柔囚笼';desc='占有被写进每一次选择，但笼门必须由两个人共同决定何时打开。';}else if(match<12){key='危险拉扯';desc='你们对占有的想象锋利地错开了；真正刺激的下一步，是把红线一条条说清。';}return{title:key,desc,counts:c,metrics:[['默契',heartQuizPct(match,30)],['占有',heartQuizPct(c.possess,30)],['沉沦',heartQuizPct(c.obsess,30)],['边界',heartQuizPct(c.boundary,30)],['危险',heartQuizPct(c.possess+c.obsess,30)]]};}
function heartQuizFallbackLine(g,result,c){const name=(c&&(c.remark||c.name))||'TA',map={心有灵犀:'你不用每次都解释，我还是会认出你心里朝向我的那一边。',黏人共犯:'既然你也这么想，那以后别怪我总想把你留在身边。',清醒相爱:'你可以一直做你自己，我会用靠近而不是束缚来爱你。',相爱不同频:'答案不一样没关系，我想听你把每一个为什么都说给我。',温柔同盟:'我们不必猜中全部，只要每一次都愿意继续了解彼此。',双向沉沦:'原来你也选了这条路——那就清醒一点，和我一起沉下去。',清醒猎物:'我喜欢你心跳加快的样子，也会记得钥匙永远在你手里。',温柔囚笼:'我确实想把你藏好，但门要不要关，永远由我们一起决定。',危险拉扯:'别急着逃，也别急着追，我们先把不能碰的地方说清楚。',红线共谋:'我想要你的偏爱，不要你的恐惧；这才是我愿意守住的规则。'};return{name,text:map[result.title]||'这份答案我会记得，因为每一个选择里都有真实的你。'};}
async function heartQuizGenerateRoleLine(g,result,c){if(g.generatedBy!=='role')return;const diffs=(g.answers||[]).filter(a=>a.userChoice!==a.roleChoice).slice(-6).map(a=>'题目：'+a.question+'；'+S.me.name+'选：'+a.userText+'；你期待ta选：'+a.roleText).join('\n')||S.me.name+'的回答大多符合你的期待';try{let text=await chatAPI([{role:'system',content:buildSystem(c,{worldbookScope:'games'})+'\n你刚向'+S.me.name+'完成一份情侣问卷，结局是「'+result.title+'」。请以你本人身份留给ta一句话，必须结合你们的关系，以及ta的回答与你提前锁定的期待答案之间的差异，10到42个中文字，自然、具体、有情绪；不要标题、引号、标签、动作描写、解释或系统口吻。'},{role:'user',content:'结局说明：'+result.desc+'\n最近差异：\n'+diffs+'\n只说最后一句话。'}],{aux:true,max:120,temp:.72,timeout:60000,complete:true,roleInterceptAudit:null,roleInterceptStage:'心动审判结语'});text=String(cleanReply(text)||'').replace(/\[[^\]]*\]/g,'').replace(/[“”"]/g,'').replace(/\s+/g,' ').trim().slice(0,90);if(text&&_hq===g&&g.phase==='result'){g.roleLine=text;heartQuizSave();render();}}catch(_){} }
function heartQuizFinish(){const g=_hq,c=g&&getC(g.cid);if(!g||!c)return;g.phase='result';g.finishedAt=Date.now();g.result=heartQuizResult(g);g.roleLine=heartQuizFallbackLine(g,g.result,c).text;g.reveal=false;heartQuizSave();const rows=(g.answers||[]).map((a,i)=>({who:'me',text:'第'+(i+1)+'题「'+a.question+'」我选“'+a.userText+'”，'+(c.remark||c.name)+'期待我选“'+a.roleText+'”'+(a.reaction?'，并回应：“'+a.reaction+'”':'' )}));rows.push({who:'ta',text:'问卷结局：'+g.result.title+'。'+g.roleLine});gameSetHandoff(g.cid,'心动审判',rows);render();heartQuizGenerateRoleLine(g,g.result,c);}
function heartQuizExit(){if(_hq)heartQuizSave();_hq=null;_hqResumeCandidate=null;stack=[{p:'home'},{p:'gameshub'}];render();}
function heartQuizAgain(){if(!_hq)return;const cid=_hq.cid,mode=_hq.mode,level=_hq.level,source=_hq.source,scare=_hq.scare;_hqResumeCandidate=null;_hq={cid,phase:'setup',mode,level,source,scare};render();}
function heartQuizErase(){heartQuizDrop();_hq=null;_hqResumeCandidate=null;stack=[{p:'home'},{p:'gameshub'}];render();toast('这份问卷已结束');}
function heartQuizSetupHTML(g,c){const levels=HEART_QUIZ_LEVELS[g.mode];return `<div class="hq-shell hq-setup ${g.mode==='dark'?'dark':'white'}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 大厅</button><b>心动审判</b><button onclick="heartQuizExit()">退出</button></div><div class="hq-scroll"><section class="hq-hero"><div class="hq-kicker"><i></i>COUPLE VERDICT · 30</div><h1>${heartQuizModeName(g.mode)}</h1><p>${g.mode==='dark'?'把占有、试探和红线放上桌面。危险只属于双方自愿的游戏。':'三十次选择，看看你的回答会在多少个瞬间符合TA的期待。'}</p></section><div class="hq-partner">${av(c.avatar,'lg')}<span><b>${esc(c.remark||c.name)} 向你提问</b><small>TA期待的答案会提前锁定，答完才揭晓</small></span></div><section class="hq-section"><label><span>选择卷面</span><span>两套独立结局</span></label><div class="hq-mode-grid"><button class="hq-choice ${g.mode==='white'?'on':''}" onclick="heartQuizSetMode('white')"><b>白卷</b><small>甜蜜、默契与真实分歧</small></button><button class="hq-choice ${g.mode==='dark'?'on':''}" onclick="heartQuizSetMode('dark')"><b>黑卷</b><small>占有、控制感与边界博弈</small></button></div></section><section class="hq-section"><label><span>选择难度</span><span>固定30题</span></label><div class="hq-level-grid">${levels.map((x,i)=>`<button class="hq-choice ${g.level===i+1?'on':''}" onclick="heartQuizSetLevel(${i+1})"><b>${esc(x[0])}</b><small>${esc(x[1])}</small></button>`).join('')}</div></section><section class="hq-section"><label><span>出题方式</span><span>预览可立即开始</span></label><div class="hq-source-grid"><button class="hq-choice ${g.source==='role'?'on':''}" onclick="heartQuizSetSource('role')"><b>TA每局新出题</b><small>结合人设与记忆生成新问卷</small></button><button class="hq-choice ${g.source==='preview'?'on':''}" onclick="heartQuizSetSource('preview')"><b>预览题库</b><small>无需API，直接体验完整流程</small></button></div></section>${g.mode==='dark'?`<section class="hq-section"><button class="hq-toggle ${g.scare?'on':''}" onclick="heartQuizToggleScare()"><span>答案偏差惊吓反馈</span><i></i></button><p class="hq-note">你的答案与TA期待不一致时会出现短暂红闪、裂痕和震动。系统开启“减少动态效果”时会自动减弱。</p></section>`:''}<button class="hq-primary" onclick="heartQuizBegin()">封存期待 · 开始30题</button>${_hqResumeCandidate?`<button class="hq-resume" onclick="heartQuizResume()">继续上次 · 已答 ${(_hqResumeCandidate.answers||[]).length}/30</button>`:''}</div></div>`;}
function heartQuizLoadingHTML(g,c){return `<div class="hq-shell ${g.mode==='dark'?'dark':''}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 大厅</button><b>心动审判</b><button></button></div><div class="hq-loading"><div class="hq-seal">${gameLineIcon('heartquiz')}</div><b>${g.source==='role'?esc(c.remark||c.name)+' 正在准备问题与期待答案':'正在装订预览问卷'}</b><span>共30题<br>你回答后才会揭晓TA提前锁定的期待</span></div></div>`;}
function heartQuizPlayHTML(g,c){const q=heartQuizCurrent(),answer=g.answers[g.index],letters=['A','B','C','D'],stage=HEART_QUIZ_STAGE[Math.min(5,Math.floor(g.index/5))];if(!q)return heartQuizLoadingHTML(g,c);return `<div class="hq-shell ${g.mode==='dark'?'dark':''} ${g.scarePulse?'hq-scare':''} ${g.lovePulse?'hq-love':''}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 保存退出</button><b>心动审判</b><button onclick="heartQuizExit()">退出</button></div><div class="hq-topline"><div class="hq-progress-copy"><span>${esc(stage)}</span><span>${g.index+1} / 30</span></div><div class="hq-progress"><i style="width:${Math.round((g.index+1)*100/30)}%"></i></div></div><div class="hq-scroll"><section class="hq-question"><small>${esc(c.remark||c.name)} 已锁定期待答案</small><h2>${esc(q.q)}</h2></section><div class="hq-options">${q.options.map((opt,i)=>{const mine=answer&&answer.userChoice===i,role=answer&&answer.roleChoice===i,both=mine&&role;return `<button class="hq-option ${mine?'mine':''} ${role?'role':''} ${both?'both':''}" ${g.reveal?'disabled':''} onclick="heartQuizChoose(${i})"><i>${letters[i]}</i><span>${esc(opt)}</span><em class="mine">你</em><em class="role">TA期待</em></button>`;}).join('')}</div>${g.reveal?`<div class="hq-reveal"><small>TA希望你这样回答</small><div><b>${esc(c.remark||c.name)}</b><p>${esc(answer.roleText)}</p><span class="hq-match ${answer.userChoice===answer.roleChoice?'':'no'}">${answer.userChoice===answer.roleChoice?'符合期待':'与期待不同'}</span></div></div><button class="hq-next" onclick="heartQuizNext()">${g.index+1>=30?'查看最终结果':'下一题'}</button>`:'<p class="hq-note">答案没有现实意义上的对错；不同只表示你的回答和TA提前锁定的期待不一样。</p>'}</div><div class="hq-horror"><div><b>答案偏离</b><small>与TA锁定的期待不一致</small></div></div><div class="hq-love-fx"><i style="--x:18%;--s:18px;--d:0s">♥</i><i style="--x:37%;--s:12px;--d:.08s">♥</i><i style="--x:58%;--s:21px;--d:.03s">♥</i><i style="--x:76%;--s:14px;--d:.13s">♥</i><i style="--x:48%;--s:10px;--d:.19s">♥</i></div></div>`;}
function heartQuizResultHTML(g,c){const r=g.result||heartQuizResult(g);return `<div class="hq-shell ${g.mode==='dark'?'dark':''}"><div class="hq-nav"><button onclick="heartQuizExit()">‹ 大厅</button><b>最终结果</b><button onclick="heartQuizErase()">结束</button></div><div class="hq-scroll"><section class="hq-result-hero"><div class="hq-result-mark">${gameLineIcon('heartquiz')}</div><small>30题 · 你的回答与TA期待已揭晓</small><h1>${esc(r.title)}</h1><p>${esc(r.desc)}</p></section><section class="hq-metrics">${r.metrics.map(m=>`<div class="hq-metric"><div><span>${esc(m[0])}</span><b>${m[1]}%</b></div><i><em style="width:${m[1]}%"></em></i></div>`).join('')}</section><section class="hq-last-word"><small>TA 留给你的一句话</small><div>${av(c.avatar,'sm')}<p>${esc(g.roleLine||heartQuizFallbackLine(g,r,c).text)}</p></div></section><div class="hq-result-actions"><button onclick="heartQuizExit()">返回大厅</button><button onclick="heartQuizAgain()">换一份再测</button></div></div></div>`;}
function renderHeartQuiz(){if(!_hq){const d=heartQuizStored();if(d)_hq=heartQuizClone(d);}if(!_hq)return `<div class="hq-shell"><div class="hq-nav"><button onclick="openGames()">‹ 大厅</button><b>心动审判</b><button></button></div><div class="hq-loading"><b>没有未完成的问卷</b><span>返回游戏大厅重新选择搭档</span></div></div>`;const c=getC(_hq.cid);if(!c)return `<div class="hq-shell"><div class="hq-loading"><b>搭档已经不在通讯录</b><span>请返回游戏大厅重新选择</span></div></div>`;if(_hq.phase==='setup')return heartQuizSetupHTML(_hq,c);if(_hq.phase==='loading')return heartQuizLoadingHTML(_hq,c);if(_hq.phase==='result')return heartQuizResultHTML(_hq,c);return heartQuizPlayHTML(_hq,c);}

// Browser-only review entrance. It never runs in normal web/private sessions.
if(typeof window!=='undefined'&&typeof NORTH_PREVIEW_PARAMS==='string'&&NORTH_PREVIEW_PARAMS.includes('heartquiz')){
  window.addEventListener('load',()=>setTimeout(()=>{
    const c=getC('preview_1')||((S.contacts||[])[0]);
    if(!c)return;
    if(NORTH_PREVIEW_PARAMS.includes('heartquiz-invite')){
      const incoming=NORTH_PREVIEW_PARAMS.includes('received');
      S.messages[c.id]=[{role:incoming?'assistant':'user',type:'gameinvite',game:'heartquiz',gname:'心动审判',ge:'',status:'pending',from:incoming?'ta':undefined,id:'preview_hq_invite',time:Date.now()}];
      stack=[{p:'home'},{p:'chat',id:c.id}];
      render();
      return;
    }
    heartQuizOpenSetup(c.id);
    _hq.mode=NORTH_PREVIEW_PARAMS.includes('dark')?'dark':'white';
    _hq.level=3;
    _hq.source='preview';
    _hq.scare=true;
    render();
  },120),{once:true});
}
